--[[
================================================================################
#  КОНФИГУРАЦИОННЫЙ ФАЙЛ HYPRLAND (НОВЫЙ ФОРМАТ LUA, ВЕРСИЯ 0.55+)             #
#  Мигрировано с старого формата hyprlang (hyprland.conf)                       #
#  Снабжено подробными комментариями по архитектуре API hl.*                   #
================================================================================
--]]

-- Отключение предупреждения об автогенерации (аналог старого autogenerated = 1)
hl.config({ autogenerated = false })

--------------------------------------------------------------------------------
-- 1. МОНИТОРЫ (MONITORS)
-- В новом формате Lua для настройки мониторов используется функция hl.monitor().
-- Координаты рассчитываются на основе инвертированной декартовой системы Y.
-- Масштаб (scale) должен быть делителем физического разрешения без остатка во избежание мерцания.
--------------------------------------------------------------------------------

-- Основной дисплей ноутбука (eDP-1)
hl.monitor({
    output = "eDP-1",
    mode = "1920x1080@60",
    position = "0x0",
    scale = 1
})

-- Дополнительные дисплеи (fallback-правило с пустым output)
hl.monitor({
    output = "",
    mode = "preferred",
    position = "auto",
    scale = 1
})


--------------------------------------------------------------------------------
-- 2. МОИ ПРОГРАММЫ (ЛОКАЛЬНЫЕ ПЕРЕМЕННЫЕ LUA)
-- Вместо префикса $ в старых конфигах, теперь используются обычные локальные переменные Lua.
-- Для конкатенации строк применяется стандартный оператор Lua '..'
--------------------------------------------------------------------------------

local terminal      = "kitty"
local fileManager   = "thunar"
local menu          = "hyprshell toggle overview"
local menu2         = "wofi --show drun --normal-window"
local browser       = "firefox"
local locker        = "swaylock -f -c 000000"
local executor      = "gmrun"
local bluetoothCfg  = "blueman-manager"
local logoutAction  = "wlogout"
local obsidian      = "flatpak run md.obsidian.Obsidian"

-- Переменная, зависящая от другого значения
local voiceNarrator = terminal .. " -e sayru"


--------------------------------------------------------------------------------
-- 3. ПЕРЕМЕННЫЕ ОКРУЖЕНИЯ (ENVIRONMENT VARIABLES)
-- Настройка переменных окружения выполняется через hl.env(ИМЯ, ЗНАЧЕНИЕ).
-- Вызов hl.env() без третьего параметра не распространяет переменные на dbus.
-- Для dbus-активации (аналог старого envd) можно передать true третьим аргументом.
--------------------------------------------------------------------------------

-- Для всех критических переменных передаем третий параметр true.
-- Это принудительно экспортирует их в D-Bus и systemd (аналог старого envd),
-- благодаря чему внешние приложения (такие как Waybar) смогут беспрепятственно общаться с Hyprland.
hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")
hl.env("QT_QPA_PLATFORM", "wayland")
hl.env("GDK_BACKEND", "wayland")
hl.env("XDG_SESSION_TYPE", "wayland")
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("GTK_CSD", "1")
hl.env("OBSIDIAN_USE_WAYLAND", "1")
hl.env("QT_QPA_PLATFORMTHEME", "qt5ct")
hl.env("GRIMBLAST_EDITOR", "gimp")

-- Параметры для slurp (сохраняем оригинальные кавычки и пробелы)
hl.env("SLURP_ARGS", "-d -b -B F050F022 -b 10101022 -c ff00ff")


--------------------------------------------------------------------------------
-- 4. АВТОЗАПУСК (AUTOSTART)
-- Вся логика автозапуска перенесена в хук-обработчик "hyprland.start".
-- Внутри используется неблокирующая функция hl.exec_cmd().
--------------------------------------------------------------------------------

hl.on("hyprland.start", function()
    -- Воспроизводим оригинальное legacy поведение: запускаем исключительно autostart.sh.
    -- UWSM автоматически импортирует переменные и изолирует запущенные службы.
    hl.exec_cmd("~/.config/hypr/autostart.sh")
end)


--------------------------------------------------------------------------------
-- 5. НАСТРОЙКИ СИСТЕМЫ И ВНЕШНЕГО ВИДА (LOOK AND FEEL)
-- Все секции настроек (general, decoration, animations, master, misc, input)
-- объединяются в один вызов hl.config() для повышения производительности парсинга.
-- Булевы значения и числа передаются в их нативном Lua-виде.
--------------------------------------------------------------------------------

hl.config({
    -- Основные параметры разметки и рамок окон
    general = {
        gaps_in = 2,
        gaps_out = 4,
        border_size = 2,
        layout = "dwindle"
    },

    -- Закругление углов окон
    decoration = {
        rounding = 10
    },

    -- Системные анимации (булево true вместо старого "yes, please :)")
    animations = {
        enabled = true
    },
    -- Настройки master-компоновщика
    master = {
        new_status = "master"
    },

    -- Системные параметры обоев и логотипа
    misc = {
        force_default_wallpaper = -1, -- -1 для случайных обоев, 0/1 для отключения маскотов
        disable_hyprland_logo = false
    },

    -- Настройки клавиатуры и мыши
    input = {
        kb_layout = "us,ru",
        kb_options = "grp:alt_shift_toggle,grp:win_space_toggle",
        follow_mouse = 1 -- фокус следует за курсором мыши
    }
})


--------------------------------------------------------------------------------
-- 6. ЖЕСТЫ ТАЧПАДА (TOUCHPAD GESTURES)
-- В версиях Hyprland 0.51+ старые параметры gestures были заменены на отдельный API.
-- Функция hl.gesture() позволяет лаконично задавать свайпы.
--------------------------------------------------------------------------------

-- Свайп 3 пальцами горизонтально для переключения рабочих столов
hl.gesture({
    fingers = 3,
    direction = "horizontal",
    action = "workspace"
})


--------------------------------------------------------------------------------
-- 7. ПРИВЯЗКИ КЛАВИШ (KEYBINDINGS)
-- Функция hl.bind() принимает клавиши, диспетчер и таблицу флагов (HL.BindOptions).
-- Флаги:
--   { release = true } — срабатывание при отпускании (ранее bindr)
--   { repeating = true } — автоповтор при удержании (ранее binde)
--   { locked = true } — работает даже на экране блокировки (ранее bindl)
--------------------------------------------------------------------------------

local mainMod = "SUPER" -- Клавиша Windows / Super

-- === Быстрое переключение раскладок ввода ===
-- Для предотвращения блокировки интерфейса (GUI) мы используем встроенные асинхронные
-- функции-колбэки Lua, меняющие конфигурацию "на лету" без спавна внешних процессов hyprctl.
hl.bind("ALT + SUPER + T", function()
    hl.config({ input = { kb_layout = "tr" } })
end)

hl.bind("ALT + SUPER + R", function()
    hl.config({ input = { kb_layout = "us,ru" } })
end)


-- === Запуск пользовательских приложений ===
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(terminal))
hl.bind("CTRL + ALT + T", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + W", hl.dsp.exec_cmd(browser))
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(executor))
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd(bluetoothCfg))
hl.bind(mainMod .. " + O", hl.dsp.exec_cmd(obsidian))
hl.bind(mainMod .. " + N", hl.dsp.exec_cmd(voiceNarrator))

-- Переключение полноэкранного режима (используем новый типизированный диспетчер)
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen())

-- Открытие главного меню и обзора (срабатывает при отпускании SUPER)
hl.bind("SUPER + SUPER_L", hl.dsp.exec_cmd(menu), { release = true })
hl.bind("SUPER + Tab", hl.dsp.exec_cmd(menu2))

-- Включение/выключение ночного режима
hl.bind(mainMod .. " + F9", hl.dsp.exec_cmd("fish -c toggle_night_mode"))


-- === Системные действия ===
-- killactive теперь заменен на close() — изящное закрытие окна
hl.bind(mainMod .. " + C", hl.dsp.window.close())
hl.bind("ALT + F4", hl.dsp.window.close())

-- Управление сессией
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd(logoutAction))
hl.bind(mainMod .. " + SHIFT + M", hl.dsp.exit())

-- Переключение плавающего режима (новый типизированный синтаксис)
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))

-- Блокировщик экрана
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd(locker))

-- Вызов шпаргалок из waybar
hl.bind(mainMod .. " + H", hl.dsp.exec_cmd("~/.config/waybar/show_shortcuts.sh"))
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd("~/.config/waybar/show_shortcuts.sh --bash"))

-- Разделение окон dwindle (togglesplit перенесен в layout)
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))


-- === Скриншоты (Screenshots) ===
-- Используем многострочный синтаксис Lua [[ ]] для предотвращения конфликтов экранирования символов bash.
hl.bind("Print", hl.dsp.exec_cmd("grimblast copy area"))

hl.bind("SHIFT + Print", hl.dsp.exec_cmd([[grimblast save screen $(xdg-user-dir PICTURES)/screens/screen-"$(date +%s)".png && notify-send -u normal -i accessories-screenshot "скриншот" "сохранен"]]))

hl.bind("CTRL + Print", hl.dsp.exec_cmd([[grimblast save area $(xdg-user-dir PICTURES)/screens/screen-"$(date +%s)".png && notify-send -u normal -i accessories-screenshot "скриншот (область)" "сохранена"]]))

hl.bind("SUPER + p", hl.dsp.exec_cmd("grimblast save active"))
hl.bind("SUPER + ALT + p", hl.dsp.exec_cmd("grimblast save output"))
hl.bind("SUPER + CTRL + p", hl.dsp.exec_cmd("grimblast save screen"))


-- === Управление мультимедиа и яркостью (Laptop keys) ===
-- Используем bindel (repeating + locked), чтобы клавиши работали заблокированными и повторялись при зажатии.
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%+"), { repeating = true, locked = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"), { repeating = true, locked = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"), { locked = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"), { locked = true })
hl.bind("XF86MonBrightnessUp",   hl.dsp.exec_cmd("brightnessctl s 10%+"), { repeating = true, locked = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl s 10%-"), { repeating = true, locked = true })

-- Мультимедийные клавиши плеера (требуют playerctl)
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"), { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"), { locked = true })


-- === Навигация по фокусу окон ===
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))


-- === Перемещение окон (Move Windows) ===
hl.bind(mainMod .. " + SHIFT + left",  hl.dsp.window.move({ direction = "left" }))
hl.bind(mainMod .. " + SHIFT + right", hl.dsp.window.move({ direction = "right" }))
hl.bind(mainMod .. " + SHIFT + up",    hl.dsp.window.move({ direction = "up" }))
hl.bind(mainMod .. " + SHIFT + down",  hl.dsp.window.move({ direction = "down" }))


-- === Управление плавающими окнами (Relative Move & Resize) ===
-- moveactive и resizeactive в 0.55+ принимают строго числовые относительные пиксели.
hl.bind(mainMod .. " + ALT + right", hl.dsp.window.move({ x = 50, y = 0, relative = true }))
hl.bind(mainMod .. " + ALT + left",  hl.dsp.window.move({ x = -50, y = 0, relative = true }))
hl.bind(mainMod .. " + ALT + up",    hl.dsp.window.move({ x = 0, y = -50, relative = true }))
hl.bind(mainMod .. " + ALT + down",  hl.dsp.window.move({ x = 0, y = 50, relative = true }))

hl.bind(mainMod .. " + CTRL + left",  hl.dsp.window.resize({ x = -50, y = 0, relative = true }))
hl.bind(mainMod .. " + CTRL + right", hl.dsp.window.resize({ x = 50, y = 0, relative = true }))
hl.bind(mainMod .. " + CTRL + up",    hl.dsp.window.resize({ x = 0, y = -50, relative = true }))
hl.bind(mainMod .. " + CTRL + down",  hl.dsp.window.resize({ x = 0, y = 50, relative = true }))


-- === Рабочие столы (Workspaces) ===
-- Оптимизируем переключение по рабочим столам 1-10 через циклы Lua.
-- Это заменяет 20 громоздких строк на лаконичные циклы.
for i = 1, 10 do
    local ws = tostring(i)
    local key = tostring(i % 10) -- рабочему столу 10 соответствует клавиша 0

    -- Переключение на рабочий стол
    hl.bind(mainMod .. " + " .. key, hl.dsp.focus({ workspace = ws }))

    -- Перемещение активного окна на рабочий стол
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = ws }))
end


-- === Специальные рабочие столы (Scratchpads) ===
hl.bind(mainMod .. " + s", hl.dsp.focus({ workspace = "special:magic" }))
hl.bind(mainMod .. " + SHIFT + s", hl.dsp.window.move({ workspace = "special:magic" }))

-- Прокрутка рабочих столов колесиком мыши с зажатой SUPER
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))


-- === Мышь: Перемещение и изменение размеров ===
-- bindm для биндинга действий мыши. Флаг { mouse = true } обязателен.
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })


--------------------------------------------------------------------------------
-- 8. ПРАВИЛА ПОВЕДЕНИЯ ОКОН (WINDOW RULES)
-- Вместо разрозненных windowrule и windowrulev2, в Lua используется функция hl.window_rule().
-- Она принимает таблицу с полями name (тип правила/действия) и match (критерии совпадения по регулярным выражениям).
--------------------------------------------------------------------------------

-- Фикс перетаскивания окон в XWayland (отключение фокуса на пустых окнах)
-- hl.window_rule({
--     name = "nofocus",
--     match = { class = "^ $", title = "^$", xwayland = 1, floating = 1, fullscreen = 0, pinned = 0 }
-- })

-- Отключение полноэкранного режима (maximize) для всех окон, кроме MPV
hl.window_rule({
    name = "float off",
    match = { class = "^(?!mpv$).*" }
})

-- Настройки для медиаплеера MPV (фокус и запрет гашения экрана)
hl.window_rule({
    name = "focus_on_activate true, idle_inhibit none",
    match = { class = "^mpv$" }
})

-- Правила для плеера ffplay-yt (настройка геометрии)
hl.window_rule({ name = "float 1", match = { class = "^ffplay-yt$" } })
hl.window_rule({ name = "pin 0",   match = { class = "^ffplay-yt$" } })
hl.window_rule({ name = "size 1280 720", match = { class = "^ffplay-yt$" } })
hl.window_rule({ name = "center 1", match = { class = "^ffplay-yt$" } })

-- Правила для Qmmp (разрешаем плавающий режим, запрещаем центрирование)
hl.window_rule({
    name = "float on, center off",
    match = { class = "^qmmp$" }
})

-- Плавная прозрачность для всех плавающих окон
hl.window_rule({
    name = "opacity 0.9 0.7 override",
    match = { float = true }
})

-- Отключить блюр для всех плавающих окон
hl.window_rule({
    name = "no_blur on",
    match = { float = true }
})

-- Убрать тень у всех НЕ плавающих окон
hl.window_rule({
    no_shadow = true,
    match = { float = false }
})




--------------------------------------------------------------------------------
-- 9. ОБРАБОТКА ДАТЧИКОВ И ПЕРЕКЛЮЧАТЕЛЕЙ (SWITCHES)
-- Например, событие закрытия/открытия крышки ноутбука для переключения экранов.
--------------------------------------------------------------------------------

-- Включаем/выключаем экраны (dpms) при работе Lid Switch
hl.bind("switch:on:Lid Switch", hl.dsp.dpms({ action = "off" }), { locked = true })
hl.bind("switch:off:Lid Switch", hl.dsp.dpms({ action = "on" }), { locked = true })


--------------------------------------------------------------------------------
-- 10. ПОДКЛЮЧЕНИЕ ЦВЕТОВОЙ СХЕМЫ (COLORS IMPORT)
-- Подключаем вынесенный в отдельный файл colors-модуль.
-- Файл должен лежать по пути ~/.config/hypr/myColors.lua
--------------------------------------------------------------------------------

require("myColors")
